import {weeklyVolume} from './analytics.js';
import * as local from './storage.js';
// UI controllers are kept in this module so the private journal has no third-party runtime.
import {esc,pace,duration,splitChart,weightChart,sleepHistory} from './charts.js';
let state=null,csrf=null,offline=false,route=location.hash.slice(1)||'today',selectedId=null,nightId=null,detail=null,feedbackDraft=null,feedbackRevision=0,historyFilter='all',historyQuery='',exploreRange='all',sleepDays=14,draftTimer=null;
const root=document.getElementById('app');
const paths={today:'<path d="m4 10 8-7 8 7v10h-6v-6h-4v6H4Z"/>',sessions:'<path d="m3 15 5-7 4 8 4-12 5 9"/>',sleep:'<path d="M20 15.2A8.4 8.4 0 0 1 8.8 4a8.5 8.5 0 1 0 11.2 11.2Z"/>',explore:'<path d="M4 20V10m8 10V4m8 16v-7"/>',plan:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 11h16m-11 5h2m3 0h2"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="m14 5-7 7 7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 3-1 3-3 1-3 3v4l3 1 1 3 3 3h4l1-3 3-1 3-3v-4l-3-1-1-3-3-3Z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',strength:'<path d="m6 7 11 11M3 8l5-5m8 18 5-5M3 12l9-9m0 18 9-9"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.arrow}</svg>`;
const formatDate=(date,options={day:'numeric',month:'short'})=>date?new Intl.DateTimeFormat('en-AU',{...options,timeZone:'Australia/Melbourne'}).format(new Date(date.length===10?`${date}T12:00:00+11:00`:date)):'Date not recorded';
const clock=date=>date?new Intl.DateTimeFormat('en-AU',{hour:'numeric',minute:'2-digit',timeZone:'Australia/Melbourne'}).format(new Date(date)):'—';
const localTimeInput=date=>{if(!date)return'';const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Australia/Melbourne',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(date));return parts.replace(' ','T');};
const label=text=>`<p class="eyebrow">${text}</p>`;
const primary=(text,attrs='',name='arrow')=>`<button class="primary" ${attrs}>${text}${icon(name)}</button>`;
const link=(text,attrs='')=>`<button type="button" class="text-button" ${attrs}>${text}${icon('arrow')}</button>`;
const activity=()=>state.activities.find(a=>a.id===selectedId);
const cleanActivities=()=>state.activities.filter(a=>!a.pendingDuplicate);
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),5000);}
async function api(path,data){const response=await fetch(path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-Stride-Csrf':csrf||''},body:data===undefined?undefined:JSON.stringify(data)});let result;try{result=await response.json();}catch{throw new Error('The server response could not be read. Try again.');}if(!response.ok){const e=new Error(result.error||'This action could not be completed.');e.status=response.status;e.current=result.current;throw e;}return result;}
async function refresh(){try{state=await api('/api/state');offline=false;for(const k of await local.keys())if(String(k).startsWith('outbox:')){const p=await local.read(k);if(!p.conflict)optimistic(p.path,p.payload);}await local.write('snapshot',state);}catch(e){if(e.status)throw e;const cached=await local.read('snapshot');if(!cached)throw e;state=cached;offline=true;}applyTheme();}
function applyTheme(){const theme=state?.settings?.theme||'dark';document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;}
function optimistic(path,payload){if(!state)return;const key=path.split('/').at(-1),collection={feedback:'feedback',activity:'activities',sleep:'sleeps',plan:'plans',weight:'weights'}[key];if(collection){const value=payload[key],recordId=key==='feedback'?payload.activityId:value.id,old=state[collection].find(r=>r.id===recordId);const next={...old,...value,id:recordId,revision:(payload.revision||0)+1,updated:new Date().toISOString(),pending:true,provider:old?.provider||'Manual'};state[collection]=[next,...state[collection].filter(r=>r.id!==recordId)];}if(key==='settings')state.settings={...state.settings,...payload.settings,revision:(payload.revision||0)+1};}
async function queueSave(path,payload){for(const kind of ['activity','sleep','plan'])if(payload[kind]&&!payload[kind].id)payload[kind].id=crypto.randomUUID();const mutationId=payload.mutationId||crypto.randomUUID(),key=`outbox:${mutationId}`;await local.write(key,{path,payload:{...payload,mutationId},at:new Date().toISOString()});try{const result=await api(path,{...payload,mutationId});await local.remove(key);offline=false;return{result,queued:false};}catch(e){if(e.status===409){await local.write(key,{path,payload:{...payload,mutationId},conflict:true,current:e.current,at:new Date().toISOString()});await updateQueueStatus();throw e;}if(e.status&&e.status!==401&&e.status<500){await local.remove(key);throw e;}offline=true;optimistic(path,payload);await local.write('snapshot',state);return{queued:true};}}
async function syncQueue(){if(!csrf){try{csrf=(await api('/api/auth')).csrf;}catch{return;}}if(!csrf)return;const keys=(await local.keys()).filter(k=>String(k).startsWith('outbox:'));let saved=0;for(const key of keys){const item=await local.read(key);if(item.conflict)continue;try{await api(item.path,item.payload);await local.remove(key);saved++;}catch(e){if(e.status===409)await local.write(key,{...item,conflict:true,current:e.current});else break;}}if(saved){toast(`${saved} saved change${saved>1?'s':''} synced.`);await refresh();if(route!=='checkin')render();}updateQueueStatus();}
async function updateQueueStatus(){const count=(await local.keys()).filter(k=>String(k).startsWith('outbox:')).length;const el=document.getElementById('sync-label');if(el){el.textContent=count?`${count} waiting to sync`:offline?'Offline · saved on this device':'Private journal';el.classList.toggle('pending',count>0||offline);}return count;}
async function go(next,idValue){if(next==='checkin'){selectedId=idValue||selectedId||cleanActivities()[0]?.id;if(!selectedId){manualActivity();return;}await loadDraft();}if(next==='session'){selectedId=idValue||selectedId||cleanActivities()[0]?.id;detail=null;try{detail=await api(`/api/activity/${encodeURIComponent(selectedId)}`);}catch{detail={activity:activity(),sources:activity()?.sources||[]};}}if(selectedId)await local.write('selectedId',selectedId);route=next;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});document.getElementById('main')?.focus({preventScroll:true});}
function shell(content){const items=[['today','Today'],['sessions','Sessions'],['sleep','Sleep'],['explore','Explore'],['plan','Plan']];return`<aside class="sidebar"><a href="#today" class="brand" data-go="today">STRIDE<span>INTELLIGENCE</span></a><p class="sidebar-caption">A little more understanding.</p><nav aria-label="Desktop navigation">${items.map(([key,name])=>`<button data-go="${key}" class="${route===key||route==='session'&&key==='sessions'?'active':''}">${icon(key)}${name}</button>`).join('')}</nav><button class="sidebar-data" data-go="data">${icon('settings')}Data & privacy</button><div class="sidebar-foot">ONE ATHLETE.<br>THE WHOLE PICTURE.</div></aside><div class="app-column"><header class="topbar"><a href="#today" class="brand mobile-brand" data-go="today">STRIDE<span>/ INTELLIGENCE</span></a><span class="desktop-context">${({today:'Your daily read',sessions:'Your training history',session:'Session story',sleep:'The other half of your story',checkin:'Your side of the story',explore:'Patterns, in perspective',plan:'Room to adapt',data:'Your data, in your hands'})[route]||'Your journal'}</span><div class="top-actions"><button class="icon-button" data-action="quick-log" aria-label="Quick log">${icon('plus')}</button><button class="icon-button" data-go="data" aria-label="Data and privacy">${icon('settings')}</button></div></header><div class="connection-line"><button id="sync-label" data-action="outbox">${offline?'Offline · saved on this device':'Private journal'}</button><span>${formatDate(state.today,{weekday:'short',day:'numeric',month:'short'})}</span></div><main id="main" tabindex="-1" class="page page-${route}">${content}</main><nav class="bottom-nav" aria-label="Main navigation">${items.map(([key,name])=>`<button data-go="${key}" ${route===key||route==='session'&&key==='sessions'?'aria-current="page"':''}>${icon(key)}<span>${name}</span></button>`).join('')}</nav></div>`;}
function sessionRow(a){const f=state.feedback.find(f=>f.id===a.id);return`<button class="activity-row" data-session="${esc(a.id)}"><span class="activity-glyph">${icon(a.type==='strength'?'strength':'sessions')}</span><span class="activity-copy"><strong>${esc(a.title)}</strong><small>${formatDate(a.date)} · ${a.distanceKm?`${a.distanceKm.toFixed(2)} km`:a.movingSeconds?`${Math.round(a.movingSeconds/60)} min`:'Summary only'}${a.type==='run'&&(a.reportedPaceSeconds||a.derivedPaceSeconds)?` · ${pace(a.reportedPaceSeconds||a.derivedPaceSeconds)} /km`:''}</small></span><span class="row-status">${f?icon('check'):icon('arrow')}</span></button>`;}
function todayPage(){const insight=state.insights[0],latest=cleanActivities()[0],latestNight=state.sleeps.find(n=>n.type==='night'),next=state.plans.find(p=>p.date>=state.today&&['planned','moved'].includes(p.status));const weights=state.weights,weight=weights.at(-1);return`<div class="today-layout"><section class="lead-section">${label(insight?`THE FIND / ${formatDate(insight.date).toUpperCase()}`:'YOUR TRAINING, IN PERSPECTIVE')}${insight?`${insight.hero!==undefined?`<div class="hero-number"><span>${esc(insight.hero)}</span><div>${esc(insight.unit)}<small>${esc(insight.heroLabel)}</small></div></div>`:''}<h1>${esc(insight.headline)}</h1><p class="lead-copy">${esc(insight.body)}</p>${insight.type==='pacing'?splitChart(state.activities.find(a=>a.id===insight.activityId)):''}${link('Behind the finding',`data-insight="${esc(insight.id)}"`)}`:`<div class="intro-mark">${icon('sessions')}</div><h1>Your next chapter<br>starts here.</h1><p class="lead-copy">Bring your runs and weight history together. A useful observation starts with your own records.</p>${primary('Import your history','data-action="import"','upload')}`}</section><div class="today-aside">${latest?`<section class="latest-session">${label('LAST RECORDED SESSION')}${sessionRow(latest)}${!state.feedback.some(f=>f.id===latest.id)?link('Add how it felt',`data-checkin="${esc(latest.id)}"`):'<p class="subtle">Your check-in is part of the story.</p>'}</section>`:''}<section class="sleep-teaser"><div class="section-title"><span>${icon('sleep')}</span><p>Make room for rest.</p></div>${latestNight?`<p class="teaser-value">${latestNight.durationMinutes!==null?duration(latestNight.durationMinutes):latestNight.rest?esc(latestNight.rest):'Morning note'}<small>${formatDate(latestNight.date)} · ${esc(latestNight.provider)}</small></p>`:'<p>Your nights belong alongside your training. Start with a note, with or without a watch.</p>'}${link('Your sleep story','data-go="sleep"')}</section>${weight?`<button class="weight-teaser" data-go="explore"><span>${label(`WEIGHT / ${weights.length} ENTRIES`)}<strong>${weight.kg.toFixed(1)} <small>kg</small></strong><small>Latest · ${formatDate(weight.date)}</small></span>${weightChart(weights,{compact:true})}</button>`:''}${next?`<section class="next-plan">${label('ON YOUR PLAN')}<h3>${esc(next.title)}</h3><p>${formatDate(next.date)}${next.durationMinutes?` · ${next.durationMinutes} min`:''}</p>${link('See your plan','data-go="plan"')}</section>`:''}</div></div>${state.insights.length>1?`<section class="more-findings"><div class="section-title"><h2>A little more to notice.</h2><span>${state.insights.length-1} observations</span></div>${state.insights.slice(1,4).map(i=>`<button class="finding-row" data-insight="${esc(i.id)}"><span><small>${formatDate(i.date)} · ${i.category==='hypothesis'?'An association':'From your records'}</small><strong>${esc(i.headline)}</strong></span>${icon('arrow')}</button>`).join('')}</section>`:''}`;}
function sessionsPage(){let rows=state.activities.filter(a=>!a.pendingDuplicate&&(historyFilter==='all'||a.type===historyFilter)&&`${a.title} ${a.date} ${a.provider}`.toLowerCase().includes(historyQuery.toLowerCase()));return`<div class="page-heading">${label('YOUR TRAINING JOURNAL')}<h1>Every session<br>has a story.</h1><p class="lead-copy">${cleanActivities().length} recorded sessions. Details worth keeping.</p></div><div class="toolbar"><div class="segments" aria-label="Activity filter">${[['all','All'],['run','Running'],['strength','Strength'],['cardio','Cardio']].map(([v,l])=>`<button data-filter="${v}" aria-pressed="${v===historyFilter}">${l}</button>`).join('')}</div><button class="icon-button" data-action="new-activity" aria-label="Add a historical activity">${icon('plus')}</button></div><label class="search-label">Find a session<input type="search" id="history-search" placeholder="Name, date or source" value="${esc(historyQuery)}"></label><div class="session-list">${rows.length?rows.map(sessionRow).join(''):'<div class="quiet-empty"><h2>No sessions here yet.</h2><p>Try another filter, import a file or add a historical session.</p></div>'}</div>${state.activities.some(a=>a.pendingDuplicate)?link('Review possible duplicate sessions','data-action="duplicates"'):''}<p class="footnote">Imported history reflects the records you have supplied. Missing days do not mean rest days.</p>`;}
function sessionPage(){const a=detail?.activity||activity();if(!a)return'<h1>Session unavailable.</h1>'+link('Back to sessions','data-go="sessions"');const f=state.feedback.find(f=>f.id===a.id),sourcePace=a.reportedPaceSeconds||a.derivedPaceSeconds;return`<button class="back-link" data-go="sessions">${icon('back')}Sessions</button><div class="session-header">${label(`${formatDate(a.date,{weekday:'short',day:'numeric',month:'long',year:'numeric'}).toUpperCase()} / ${esc(a.provider).toUpperCase()}`)}<h1>${esc(a.title)}.</h1><p class="subtle">${a.start?clock(a.start):'Date-level record'} · ${a.type==='run'?'Running':a.type==='strength'?'Strength':'Cardio'}</p></div><div class="session-layout"><div><div class="session-numbers">${a.distanceKm?`<div><strong>${a.distanceKm.toFixed(2)}<small>km</small></strong><span>Distance</span></div>`:''}<div><strong>${a.movingSeconds?pace(a.movingSeconds):'—'}<small>${a.movingSeconds?'min':''}</small></strong><span>${a.movingSeconds?'Recorded duration':'Duration absent'}</span></div>${a.type==='run'?`<div><strong>${sourcePace?pace(sourcePace):'—'}<small>${sourcePace?'/km':''}</small></strong><span>${a.reportedPaceSeconds?'Reported pace':a.derivedPaceSeconds?'Calculated pace':'Pace absent'}</span></div>`:''}</div>${a.type==='run'?`<h2 class="chart-title">Your rhythm, kilometre by kilometre.</h2>${splitChart(a)}`:''}${a.sets?.length?`<section class="sets-section"><h2>The work you did.</h2><table><thead><tr><th>Exercise</th><th>Sets × reps</th><th>Load</th></tr></thead><tbody>${a.sets.map(s=>`<tr><td>${esc(s.exercise)}</td><td>${s.sets||'—'} × ${s.reps||'—'}</td><td>${s.kg??'—'} kg</td></tr>`).join('')}</tbody></table></section>`:''}${a.note?`<section class="source-note">${label('IN YOUR WORDS')}<blockquote>“${esc(a.note)}”</blockquote><small>Original ${esc(a.provider)} note</small></section>`:''}<dl class="metric-list">${[['Ascent',a.elevationGainM!==null&&a.elevationGainM!==undefined?`${a.elevationGainM} m`:'Not recorded'],['Steps',a.steps?.toLocaleString()||'Not recorded'],['Heart rate',a.heartRate?`${a.heartRate} bpm`:'Not recorded'],['Cadence',a.cadence?`${a.cadence} steps/min`:'Not recorded']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></div><aside class="session-aside">${f?`<section class="feedback-summary">${label('HOW IT FELT')}<h2>${f.effort}/10 <span>effort</span></h2><div class="feedback-tags">${[f.talk?({full:'Full sentences',short:'Short phrases',barely:'Barely talking'})[f.talk]:null,f.discomfort?({none:'No discomfort reported',mild:'Mild discomfort',affected:'Discomfort affected run'})[f.discomfort]:null,f.reserve?({plenty:'Plenty left',some:'Some left',none:'Nothing left'})[f.reserve]:null,f.completion].filter(Boolean).map(v=>`<span>${esc(v)}</span>`).join('')}</div>${f.note?`<p class="note-copy">${esc(f.note)}</p>`:''}<small>Saved ${formatDate(f.updated)} · editable anytime</small></section>`:`<section class="feedback-summary">${label('THE PART ONLY YOU KNOW')}<h2>How did it feel?</h2><p>Four quick answers can add meaning to the numbers.</p></section>`}${primary(f?'Edit check-in':'Add how it felt',`data-checkin="${esc(a.id)}"`)}${link('Source & calculations','data-action="session-evidence"')}${link('Edit history',`data-history="activity" data-id="${esc(a.id)}"`)}${link('Edit session','data-action="edit-activity"')}${a.type==='strength'?link('Add sets & reps','data-action="edit-activity"'):''}${link('Link to a plan','data-action="link-plan"')}${link('Archive session',`data-archive="activity" data-id="${esc(a.id)}"`)}</aside></div>`;}
function sleepPage(){const nights=state.sleeps.filter(s=>s.type==='night'),n=state.sleeps.find(s=>s.id===nightId)||nights[0];if(!n)return`${label('SLEEP / YOUR WHOLE PICTURE')}<div class="sleep-layout empty-sleep"><div><div class="night-art" aria-hidden="true"><div class="moon"></div><i class="orbit"></i><i class="orbit second"></i><span>REST</span></div><h1>Every day starts<br>the night before.</h1><p class="lead-copy">Your nights belong alongside your training. Start with what you remember; a watch can fill in more later.</p></div><section class="empty-night"><span class="tag">${state.garmin.configured?'Garmin awaiting first sync':'No watch connected'}</span><h2>No nights recorded yet.</h2><p>Duration and timing will appear here. No score to chase, no gaps to make up for.</p><div class="empty-week" aria-label="No recorded nights">${['S','M','T','W','T','F','S'].map(d=>`<span>${d}<i></i></span>`).join('')}</div>${primary('Add a night','data-action="sleep-note"','plus')}<small>Optional. A few taps, whenever you feel like it.</small>${link('When your Garmin arrives','data-action="garmin-info"')}</section></div>`;
  const stages=n.stageTotals?Object.entries(n.stageTotals).filter(([,v])=>v!==null):[],summary=state.sleepSummary,nap=state.sleeps.filter(x=>x.type==='nap'&&x.date===n.date);return`<div class="page-heading">${label(`SLEEP / ${formatDate(n.date).toUpperCase()}`)}<h1>A little more<br>of the picture.</h1></div><div class="sleep-layout"><section><div class="night-main"><div class="sleep-duration">${n.durationMinutes!==null?duration(n.durationMinutes):'A morning note'}</div><p class="subtle">${n.durationOrigin?esc(n.durationOrigin):'Your own observation'} · wake date ${formatDate(n.date)}</p>${n.start&&n.end?`<div class="night-interval"><div><span>Sleep start</span><b>${clock(n.start)}</b><small>${formatDate(n.start)}</small></div><span class="interval-rule"></span><div><span>Wake</span><b>${clock(n.end)}</b><small>${formatDate(n.end)}</small></div></div>`:''}${n.rest?`<p class="rested-line">You felt <strong>${esc(n.rest)}</strong> on waking.</p>`:''}${n.note?`<p class="note-copy">${esc(n.note)}</p>`:''}${link('Edit this night',`data-sleep-edit="${esc(n.id)}"`)}${link('Edit history',`data-history="sleep" data-id="${esc(n.id)}"`)}</div><div class="toolbar"><h2>Your nights, over time.</h2><div class="segments">${[7,14,28].map(d=>`<button data-sleep-days="${d}" aria-pressed="${sleepDays===d}">${d}d</button>`).join('')}</div></div>${sleepHistory(nights,state.today,sleepDays)}${nights.filter(x=>x.date===n.date).length>1?'<p class="footnote">Multiple main-sleep records share this wake date. Edit and archive the duplicate to include this date in trends.</p>':''}${stages.length?`<section class="stage-totals"><h2>Garmin’s stage estimates.</h2><p class="subtle">Totals for the night. Stage timestamps were not supplied.</p>${stages.map(([k,v])=>`<div><span>${k}</span><div class="stage-track"><i style="width:${Math.min(100,v/Math.max(1,(n.durationMinutes||0)*60+(n.stageTotals.awake||0))*100)}%"></i></div><b>${Math.round(v/60)} min</b></div>`).join('')}</section>`:''}</section><aside class="sleep-aside">${primary('Add a night','data-action="sleep-note"','plus')}${n.score!==null&&n.score!==undefined||n.hrv||n.heartRate?`<dl class="metric-list"><div><dt>Garmin Sleep Score<small>Device estimate</small></dt><dd>${n.score??'Not available'}</dd></div>${n.respiration?`<div><dt>Overnight respiration<small>Garmin estimate</small></dt><dd>${n.respiration} /min</dd></div>`:''}${n.stress!=null?`<div><dt>Sleep stress<small>Garmin estimate</small></dt><dd>${n.stress}</dd></div>`:''}${n.hrv?`<div><dt>Overnight HRV<small>Garmin average</small></dt><dd>${n.hrv} ms</dd></div>`:''}${n.heartRate?`<div><dt>Overnight heart rate<small>Garmin average</small></dt><dd>${n.heartRate} bpm</dd></div>`:''}${state.settings.showSpo2&&n.spo2?`<div><dt>Garmin overnight SpO₂<small>Device estimate</small></dt><dd>${n.spo2}%</dd></div>`:''}</dl>`:''}${summary.recordedNights>=3?`<section class="week-summary">${label('PAST 7 DAYS')}<h2>${duration(summary.medianMinutes)}</h2><p>Median across ${summary.recordedNights} recorded nights.</p></section>`:''}${nap.length?`<section><h2>Naps · ${formatDate(n.date)}</h2>${nap.map(x=>`<button class="night-row" data-sleep-edit="${esc(x.id)}">${clock(x.start)} <b>${duration(x.durationMinutes)}</b></button>`).join('')}</section>`:''}<section class="night-list"><h2>Recorded mornings</h2>${nights.slice(0,20).map(x=>`<button class="night-row ${x.id===n.id?'selected':''}" data-night="${esc(x.id)}"><span>${formatDate(x.date)}</span><b>${x.durationMinutes!==null?duration(x.durationMinutes):'Note'}</b></button>`).join('')}</section>${link('Sleep & Garmin setup','data-go="data"')}</aside></div>`;}
function explorePage(){const volume=weeklyVolume(cleanActivities(),state.today);const latest=state.weights.at(-1),end=latest?.date;let weights=state.weights;if(end&&exploreRange!=='all'){const cutoff=new Date(end+'T12:00:00Z');cutoff.setUTCDate(cutoff.getUTCDate()-Number(exploreRange));weights=weights.filter(w=>w.date>=cutoff.toISOString().slice(0,10));}const first=weights[0],last=weights.at(-1),change=first&&last?last.kg-first.kg:null;return`${label('EXPLORE / A LONGER VIEW')}<div class="explore-heading"><h1>Patterns, in<br>perspective.</h1><p class="lead-copy">A useful view of what you’ve actually recorded.</p></div><section class="volume-section"><div class="section-title"><h2>This week, as recorded.</h2><small>${formatDate(volume.start)}–${formatDate(volume.end)}</small></div><div class="volume-numbers"><div><strong>${volume.sessions}</strong><small>sessions</small></div><div><strong>${volume.distanceKm.toFixed(2)}</strong><small>running km</small></div><div><strong>${Math.round(volume.minutes)}</strong><small>recorded minutes</small></div></div><p class="footnote">Imported records only. ${volume.missingDuration?`${volume.missingDuration} sessions have no duration.`:"Missing days do not imply rest."}</p></section><section class="weight-section"><div class="toolbar"><h2>Weight, over time.</h2><div class="segments">${[['30','30d'],['90','90d'],['all','All']].map(([v,l])=>`<button data-range="${v}" aria-pressed="${exploreRange===v}">${l}</button>`).join('')}</div></div>${last?`<div class="weight-head"><strong>${last.kg.toFixed(1)} <small>kg</small></strong><p>Latest · ${formatDate(last.date)}<span>${weights.length} records${weights.length>1?` · ${Math.abs(change).toFixed(1)} kg ${change<0?'lower':'higher'} than the first in view`:''}</span></p></div>${weightChart(weights)}<p class="footnote">The comparison uses recorded endpoints. Day-to-day weight changes are not the same as body-fat changes.</p><details><summary>Inspect ${weights.length} measurements</summary><table><thead><tr><th>Date</th><th>Weight</th><th>Source</th></tr></thead><tbody>${weights.map(w=>`<tr><td>${formatDate(w.date)}</td><td>${w.kg.toFixed(1)} kg</td><td>${esc(w.provider)}</td></tr>`).join('')}</tbody></table></details>`:`<div class="quiet-empty"><h2>Your weight history has a home here.</h2><p>Import your MASS export to see your actual measurements.</p>${primary('Import MASS','data-action="import"','upload')}</div>`}</section><section class="explore-observations"><h2>What else is worth noticing?</h2>${state.insights.filter(i=>i.type!=='pacing').map(i=>`<button class="finding-row" data-insight="${esc(i.id)}"><span><small>${formatDate(i.date)} · ${i.category==='hypothesis'?'An association':'From your records'}</small><strong>${esc(i.headline)}</strong></span>${icon('arrow')}</button>`).join('')||'<p class="subtle">More observations will appear when comparable records support them.</p>'}</section><section class="relationship-note"><h2>Do longer nights make runs feel easier?</h2><p>We’ll compare recorded sleep before runs of similar distance and effort once enough matched observations exist. No conclusion is drawn from missing sleep.</p></section>`;}
function planPage(){return`${label('PLAN / ROOM TO ADAPT')}<div class="page-heading"><h1>A plan that moves<br>with you.</h1><p class="lead-copy">Keep the intention. Record what actually happened.</p></div><div class="toolbar"><h2>Your sessions</h2><button class="icon-button" data-action="new-plan" aria-label="Plan a session">${icon('plus')}</button></div>${state.plans.length?state.plans.map(p=>`<button class="plan-row" data-plan="${esc(p.id)}"><div class="plan-date"><b>${formatDate(p.date,{day:'numeric'})}</b><span>${formatDate(p.date,{month:'short'})}</span></div><span><strong>${esc(p.title)}</strong><small>${esc(p.type)}${p.durationMinutes?` · ${p.durationMinutes} min`:''} · ${esc(p.status)}${p.activityId?' · linked to a session':''}</small></span>${icon('arrow')}</button>`).join(''):`<div class="quiet-empty plan-empty">${icon('plan')}<h2>Nothing prescribed here yet.</h2><p>Your original plan’s structured schedule hasn’t been verified. Add a session when you know the prescription.</p>${primary('Plan a session','data-action="new-plan"','plus')}</div>`}<a class="external-plan" href="https://symphonious-kitsune-3c1793.netlify.app/" target="_blank" rel="noopener noreferrer">Open your original workout plan ↗</a><p class="footnote">Your plan is versioned as you edit it. Move, change or skip a session without losing its original date.</p>`;}
const questions=[{key:'effort',title:'How hard did it feel?',values:Array.from({length:10},(_,i)=>[String(i+1),String(i+1)])},{key:'talk',title:'Could you talk?',values:[['full','Full sentences'],['short','Short phrases'],['barely','Barely']]},{key:'discomfort',title:'Any discomfort?',values:[['none','None'],['mild','Mild'],['affected','Affected run']]},{key:'reserve',title:'Anything left at the finish?',values:[['plenty','Plenty'],['some','Some'],['none','Nothing left']]}];
async function loadDraft(){const existing=state.feedback.find(f=>f.id===selectedId);const draft=await local.read(`draft:${selectedId}`);feedbackRevision=draft?.revision??existing?.revision??0;feedbackDraft=draft?.value||{effort:existing?.effort??null,talk:existing?.talk??null,discomfort:existing?.discomfort??null,reserve:existing?.reserve??null,completion:existing?.completion??null,location:existing?.location??null,note:existing?.note||'',legs:existing?.legs||null};}
async function saveDraft(){await local.write(`draft:${selectedId}`,{value:feedbackDraft,revision:feedbackRevision,at:new Date().toISOString()});const el=document.getElementById('draft-status');if(el)el.textContent='Draft kept on this device';}
function checkinPage(){const a=activity();if(!a||!feedbackDraft)return'<h1>Choose a session first.</h1>'+link('Your sessions','data-go="sessions"');const fields=a.type==='run'?questions:[questions[0],{key:'completion',title:'How much did you complete?',values:[['complete','All of it'],['partial','Part of it'],['changed','Changed it']]},questions[2]];const count=fields.filter(f=>feedbackDraft[f.key]!=null).length;return`<button class="back-link" data-session="${esc(a.id)}">${icon('back')}Session story</button>${label(`${formatDate(a.date).toUpperCase()} / ${esc(a.title).toUpperCase()}`)}<div class="checkin-heading"><h1>Your side<br>of the story.</h1><span class="time-pill">${a.type==='run'?'30–45':'20–30'}<small>seconds</small></span></div><div class="checkin-caption"><p>The numbers don’t tell us everything.</p><button data-action="focus-note">Add a note ↗</button></div><div class="answer-list">${fields.map((f,i)=>`<fieldset class="answer-group"><legend><span>0${i+1}</span>${f.title}</legend><div class="choices ${f.key==='effort'?'effort-choices':''}">${f.values.map(([v,l])=>`<button data-answer="${f.key}" data-value="${v}" aria-pressed="${String(feedbackDraft[f.key])===v}">${l}</button>`).join('')}</div>${f.key==='effort'?'<div class="range-hints"><span>1 · Very easy</span><span>10 · All out</span></div>':''}${f.key==='discomfort'&&feedbackDraft.discomfort&&feedbackDraft.discomfort!=='none'?`<div class="location-group"><p>Where? <small>Optional</small></p><div class="choices four">${['shin','knee','foot','other'].map(v=>`<button data-answer="location" data-value="${v}" aria-pressed="${feedbackDraft.location===v}">${v}</button>`).join('')}</div></div>`:''}</fieldset>`).join('')}</div><label class="field-label" for="checkin-note">Anything to add? <span>Optional</span></label><textarea id="checkin-note" placeholder="A thought, a niggle, a small win…" rows="2">${esc(feedbackDraft.note)}</textarea><details class="extra-context"><summary>A little more context</summary><label class="field-label" for="leg-context">Legs before starting</label><select id="leg-context"><option value="">Not answered</option>${[['normal','Normal'],['gym','Heavy from gym'],['work','Heavy from work'],['other','Other']].map(([v,l])=>`<option value="${v}" ${feedbackDraft.legs===v?'selected':''}>${l}</option>`).join('')}</select></details><div class="save-dock">${primary('Save check-in',`data-action="save-feedback" ${count<fields.length?'disabled':''}`,'check')}<p id="draft-status" role="status">${count} of ${fields.length} answered · nothing assumed</p></div>`;}
function dataPage(){return`${label('DATA & PRIVACY')}<div class="page-heading"><h1>Your journal.<br>Your control.</h1><p class="lead-copy">Stored privately on your own server. No advertising, analytics or external fonts.</p></div><div class="settings-grid"><section><h2>Bring your history.</h2><p>MASS JSON, Strava archive or CSV, FIT, TCX and GPX. Original files stay attached to their records.</p>${primary('Import a file','data-action="import"','upload')}${link('Review possible duplicates','data-action="duplicates"')}<details><summary>Import history (${state.imports.length})</summary>${state.imports.slice(0,20).map(i=>`<div class="audit-row"><strong>${esc(i.name)}</strong><small>${formatDate(i.at)} · ${i.added} added · ${i.updatedCount??0} updated · ${i.matched||0} matched</small>${(i.warnings||[]).map(w=>`<p>${esc(w)}</p>`).join('')}</div>`).join('')}</details></section><section><div class="section-title"><h2>Garmin, when you’re ready.</h2><span class="tag">${state.garmin.verified?'Live sync verified':state.garmin.configured?'Key saved · unverified':'Not connected'}</span></div><p>Personal API connection for activities, sleep and available overnight HRV. Your key stays on the server.</p>${state.garmin.lastSync?`<p class="subtle">Last sync ${formatDate(state.garmin.lastSync)}</p>`:''}${state.garmin.keyExpires?`<p class="subtle">Key expiry ${formatDate(state.garmin.keyExpires)}</p>`:''}${link(state.garmin.configured?'Replace key':'Set up Garmin','data-action="garmin-config"')}${state.garmin.configured?`${primary('Sync a date range','data-action="garmin-sync"')}${link('Disconnect Garmin','data-action="garmin-disconnect"')}`:''}<p class="footnote">Live device coverage remains unverified until your first successful sync. Stage totals appear only when supplied.</p></section><section><h2>A copy you can keep.</h2><p>Export an encrypted backup with a passphrase you choose. It includes records, original imports and edit history.</p>${link('Export encrypted backup','data-action="export"')}${link('Restore a backup','data-action="restore"')}<small>${state.settings.lastBackup?'Last export '+formatDate(state.settings.lastBackup):'No portable backup exported yet.'}</small></section><section><h2>Make it yours.</h2><form id="preferences"><label>Appearance<select name="theme">${['dark','light','system'].map(t=>`<option ${state.settings.theme===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Optional sleep target · minutes<input name="sleepTargetMinutes" type="number" min="60" max="1440" placeholder="No target" value="${state.settings.sleepTargetMinutes??''}"></label><label class="checkbox"><input type="checkbox" name="morningPrompt" ${state.settings.morningPrompt?'checked':''}>Show a gentle morning note prompt</label><label class="checkbox"><input type="checkbox" name="showSpo2" ${state.settings.showSpo2?'checked':''}>Show Garmin overnight SpO₂ when available</label>${primary('Save preferences','type="submit"','check')}</form></section><section><h2>Nothing silently disappears.</h2>${link('Saved drafts & sync queue','data-action="outbox"')}${link('Archived records','data-action="trash"')}<p>Check-in drafts and a recent view stay in this browser for offline use. Locking clears the local view after pending saves are resolved.</p>${link('Lock this journal','data-action="lock"')}</section></div>`;}
function render(){root.innerHTML=shell(({today:todayPage,sessions:sessionsPage,session:sessionPage,sleep:sleepPage,explore:explorePage,plan:planPage,checkin:checkinPage,data:dataPage}[route]||todayPage)());updateQueueStatus();if(route==='today'&&state.settings.morningPrompt&&!state.sleeps.some(s=>s.date===state.today&&s.rest))document.querySelector('.sleep-teaser')?.insertAdjacentHTML('beforeend',`<p class="subtle">How did you wake up today?</p><div class="choices morning-choices">${['rested','okay','drained'].map(v=>`<button data-morning="${v}">${v}</button>`).join('')}</div>`);}
let activeDialog=null;
function modal(title,body,onSubmit){activeDialog?.close();activeDialog?.remove();const d=document.createElement('dialog');d.className='modal';d.innerHTML=`<div class="modal-top"><h2>${esc(title)}</h2><button class="icon-button" data-close aria-label="Close dialog">${icon('close')}</button></div>${body}<p class="form-error" role="alert"></p>`;document.body.append(d);activeDialog=d;d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>{d.remove();if(activeDialog===d)activeDialog=null;});if(onSubmit)d.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(e.target)),d,e.target);}catch(err){d.querySelector('.form-error').textContent=err.message;}finally{button.disabled=false;}};d.showModal();return d;}
const field=(name,title,value='',type='text',extra='')=>`<label>${title}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(name,title,value='')=>`<label>${title}<textarea name="${name}" rows="3">${esc(value)}</textarea></label>`;
const select=(name,title,choices,value='')=>`<label>${title}<select name="${name}">${choices.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const saveButton=(title='Save')=>primary(title,'type="submit"','check');
async function saved(d,message='Saved.'){d.close();await refresh();render();toast(message);}
function editWeight(old){modal('Correct a measurement',`<form>${field('date','Date',old.date,'date','required')}${field('kg','Weight · kg',old.kg,'number','min="1" max="500" step="any" required')}${area('note','Note',old.note||'')}<p>The original MASS source stays preserved. Future imports keep this correction.</p>${saveButton()}${link('Archive measurement',`data-archive="weight" data-id="${esc(old.id)}"`)}</form>`,async(v,d)=>{await queueSave('/api/weight',{weight:{...v,id:old.id},revision:old.revision});await saved(d,'Measurement corrected.');});}
function manualActivity(old=null){modal(old?'Edit session':'Record a session',`<form>${field('title','Session name',old?.title||'')}${select('type','Activity',[['run','Running'],['strength','Strength'],['cardio','Cardio'],['other','Other']],old?.type||'run')}<div class="form-pair">${field('date','Date',old?.date||state.today,'date','required')}${field('movingMinutes','Duration · minutes',old?.movingSeconds?old.movingSeconds/60:'','number','min="0.02" step="any"')}</div>${field('startLocal','Start time · Melbourne (optional)',localTimeInput(old?.start),'datetime-local')}${select('disambiguation','If the clock repeats',[['reject','Ask me to resolve it'],['earlier','Earlier occurrence'],['later','Later occurrence']])}${field('distanceKm','Distance · km (optional)',old?.distanceKm??'','number','min="0.001" step="any"')}${area('note','Session notes',old?.note||'')}<details ${old?.type==='strength'?'open':''}><summary>Sets & reps · optional</summary><p class="subtle">One exercise per line: name, sets, reps, kg. Leave load blank for bodyweight.</p><label>Exercises<textarea name="setLines" rows="4" placeholder="Squat, 3, 8, 40">${esc((old?.sets||[]).map(s=>[s.exercise,s.sets??'',s.reps??'',s.kg??''].join(', ')).join('\n'))}</textarea></label></details>${saveButton()}</form>`,async(v,d)=>{const sets=v.setLines.trim()?v.setLines.split('\n').filter(l=>l.trim()).map(l=>{const [exercise,sets,reps,kg,...rest]=l.split(',').map(s=>s.trim());if(rest.length)throw new Error('Use exactly four columns for each exercise.');return{exercise,sets:sets||null,reps:reps||null,kg:kg||null};}):[];const result=await queueSave('/api/activity',{activity:{id:old?.id,title:v.title,type:v.type,date:v.date,start:v.startLocal?undefined:null,startLocal:v.startLocal,disambiguation:v.disambiguation,movingSeconds:v.movingMinutes?Number(v.movingMinutes)*60:null,distanceKm:v.distanceKm,note:v.note,sets},revision:old?.revision||0});if(!result.queued&&old?.id===selectedId)detail=await api(`/api/activity/${encodeURIComponent(selectedId)}`);await saved(d,result.queued?'Saved on this device. Waiting to sync.':'Session saved.');});}
function sleepNote(old=null){modal(old?'Your night, in your words':'Add sleep or a morning note',`<form><p class="subtle">Fill in what you know. Every field except wake date is optional.</p><div class="form-pair">${field('date','Wake date',old?.date||state.today,'date','required')}${select('type','Sleep type',[['night','Main sleep'],['nap','Nap']],old?.type||'night')}</div><div class="form-pair">${field('startLocal','Sleep start · Melbourne',localTimeInput(old?.start),'datetime-local')}${field('endLocal','Wake · Melbourne',localTimeInput(old?.end),'datetime-local')}</div>${select('disambiguation','If the clock repeats',[['reject','Ask me to resolve it'],['earlier','Earlier occurrence'],['later','Later occurrence']])}${field('durationMinutes','Sleep duration · minutes',old?.durationMinutes??'','number','min="0" max="2160" step="any"')}${select('rest','How rested did you feel?',[['','Not answered'],['rested','Rested'],['okay','Okay'],['drained','Drained']],old?.rest||'')}${area('note','Anything worth remembering?',old?.note||'')}${saveButton()}${old?link('Archive this record',`data-archive="sleep" data-id="${esc(old.id)}"`):''}</form>`,async(v,d)=>{const r=await queueSave('/api/sleep',{sleep:{...v,id:old?.id,start:v.startLocal?undefined:null,end:v.endLocal?undefined:null},revision:old?.revision||0});await saved(d,r.queued?'Sleep note kept on this device. Waiting to sync.':'Sleep note saved.');});}
function planEditor(old=null,linkActivity=null){modal(old?'Edit planned session':'Plan a session',`<form>${field('title','Session name',old?.title||'')}${field('date','Date',old?.date||state.today,'date','required')}${select('type','Activity',[['run','Running'],['strength','Strength'],['cardio','Cardio']],old?.type||'run')}${field('durationMinutes','Planned minutes',old?.durationMinutes??'','number','min="1" max="1440"')}${select('status','Status',['planned','complete','partial','changed','skipped','moved'].map(v=>[v,v]),old?.status||'planned')}${select('activityId','Link an actual session',[['','No session linked'],...cleanActivities().map(a=>[a.id,`${a.date} · ${a.title}`])],linkActivity||old?.activityId||'')}${area('note','Prescription / notes',old?.note||'')}${old?`<p class="footnote">Original date ${esc(old.originalDate)} · version ${old.version}</p>`:''}${saveButton()}</form>`,async(v,d)=>{const r=await queueSave('/api/plan',{plan:{...v,id:old?.id},revision:old?.revision||0});await saved(d,r.queued?'Plan saved on this device. Waiting to sync.':'Plan saved.');});}
function insightEvidence(i){modal('Behind the finding',`<span class="tag">${i.category==='hypothesis'?'Association · not causation':'Observation'}</span><h3>${esc(i.headline)}</h3><p>${esc(i.body)}</p><h3>What supports it</h3><dl class="evidence-list">${Object.entries(i.inputs).map(([k,v])=>`<div><dt>${esc(k.replace(/([A-Z])/g,' $1'))}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v):v??'Not recorded')}</dd></div>`).join('')}</dl><p class="footnote">Calculation version ${esc(i.calculationVersion)}. Derived from ${i.sourceIds.length} referenced records.</p>${i.activityId?link('Open session story',`data-session="${esc(i.activityId)}"`):i.sleepId?link('Open recorded night',`data-night="${esc(i.sleepId)}"`):link('Explore weight records','data-go="explore"')}`);api('/api/seen',{id:i.id}).catch(()=>{});}
function sessionEvidence(){const a=detail?.activity||activity();modal('Source & calculations',`<p>${esc(a.provider)} · ${esc(a.provenance||'Imported or personally recorded')}</p><dl class="evidence-list"><div><dt>Pace</dt><dd>${a.reportedPaceSeconds?'Reported by the source':a.derivedPaceSeconds?'Duration ÷ distance':'Not available'}</dd></div><div><dt>Time precision</dt><dd>${a.start?'Timestamp supplied':'Date only; no time inferred'}</dd></div><div><dt>Recorded samples</dt><dd>${a.streams?.length||a.streamCount||0}</dd></div></dl>${(a.conflicts||[]).map(c=>`<p>${esc(c)}</p>`).join('')}${(a.splits||[]).filter(s=>s.distanceOrigin).map(s=>`<p>Partial split distance: ${esc(s.distanceOrigin)}</p>`).join('')}${a.effort?`<p>Source-reported effort: ${a.effort}/10. This is separate from your editable check-in.</p>`:''}${a.sourceCaveats?`<p>${esc(a.sourceCaveats)}</p>`:''}${a.splitCaveat?`<p>${esc(a.splitCaveat)}</p>`:''}<p>Source values and your corrections are kept separately. Missing heart rate, cadence and sleep stay absent.</p>${(detail?.sources||a.sources||[]).map(s=>`<a class="source-link" href="/api/source/${encodeURIComponent(s.hash)}" download>${esc(s.name||s.provider)} · download preserved source</a>`).join('')}${a.streams?.length?`<details><summary>Inspect recorded samples</summary><div class="table-scroll"><table><thead><tr><th>Time</th><th>Distance m</th><th>HR bpm</th><th>Speed m/s</th></tr></thead><tbody>${a.streams.slice(0,100).map(s=>`<tr><td>${s.time?clock(s.time):'—'}</td><td>${s.distanceM??'—'}</td><td>${s.heartRate??'—'}</td><td>${s.speedMps??'—'}</td></tr>`).join('')}</tbody></table></div><p class="footnote">First 100 samples shown. The source contains all samples.</p></details>`:''}`);}
const toBase64=async file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error('The file could not be read.'));r.readAsDataURL(file);});
function importFile(){modal('Bring your history',`<form><p>Choose a MASS JSON, Strava ZIP/CSV, FIT, TCX or GPX file. Maximum 32 MB.</p><label>Source file<input type="file" name="file" accept=".json,.zip,.csv,.fit,.tcx,.gpx,.gz" required></label>${saveButton('Preview import')}</form>`,async(v,d,form)=>{const file=form.file.files[0];if(file.size>32*1024*1024)throw new Error('Choose a file smaller than 32 MB.');const p=await api('/api/import/preview',{name:file.name,base64:await toBase64(file)});d.close();modal('Ready to import',`<form><p><strong>${esc(file.name)}</strong></p><div class="import-counts"><span><b>${p.activities}</b>activity records</span><span><b>${p.weights}</b>weight records</span></div><p>Stable source identities are matched. Possible duplicates wait for review. ${p.ignored} deleted source sessions will be excluded.</p>${p.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}${saveButton('Import these records')}</form>`,async(_,dialog)=>{const r=await api('/api/import/commit',{key:p.key});await saved(dialog,`${r.added} added · ${r.updated} updated · ${r.matched} matched${r.pending?' · '+r.pending+' to review':''}.`);});});}
function backupExport(){modal('A private copy, wherever you keep it',`<form><p>Choose a passphrase of at least 12 characters. Keep it separately; it cannot be recovered. Garmin keys and login sessions are excluded.</p>${field('passphrase','Backup passphrase','','password','required minlength="12" autocomplete="new-password"')}${field('repeat','Repeat passphrase','','password','required minlength="12" autocomplete="new-password"')}${saveButton('Encrypt & download')}</form>`,async(v,d)=>{if(v.passphrase!==v.repeat)throw new Error('The passphrases do not match.');const backup=await api('/api/backup/export',{passphrase:v.passphrase});const url=URL.createObjectURL(new Blob([JSON.stringify(backup)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`stride-${state.today}.stride`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);await saved(d,'Encrypted backup downloaded.');});}
function backupRestore(){modal('Restore your journal',`<form><p>Preview the backup before replacing this journal. A local recovery snapshot is made first.</p><label>Encrypted STRIDE backup<input name="file" type="file" accept=".stride,.json" required></label>${field('passphrase','Backup passphrase','','password','required autocomplete="off"')}${saveButton('Preview backup')}</form>`,async(v,d,form)=>{if(await updateQueueStatus())throw new Error('Resolve pending saves before restoring.');const backup=JSON.parse(await form.file.files[0].text()),p=await api('/api/backup/preview',{backup,passphrase:v.passphrase});d.close();modal('Review before restoring',`<form><p>This backup contains ${p.summary.activities} activities, ${p.summary.weights} weights and ${p.summary.nights} sleep records, created ${formatDate(p.summary.created)}.</p><p>It replaces the current journal. Login and connector keys stay on this server.</p>${field('confirm','Type RESTORE to continue','','text','required pattern="RESTORE"')}${saveButton('Restore this backup')}</form>`,async(v,dialog)=>{await api('/api/backup/restore',{key:p.key,confirm:v.confirm});await local.clear();await saved(dialog,'Journal restored.');});});}
function garminConfigure(){modal('Connect your Garmin',`<form><p>Create a key in the <a href="https://developer.garmin.com/gc-developer-program/personal/personal-api/" target="_blank" rel="noopener noreferrer">Garmin Personal API portal ↗</a>. Then choose a date range to verify the connection.</p>${field('key','Personal API key','','password','required minlength="20" autocomplete="off"')}${field('expires','Key expiry date (optional)','','date')}${saveButton('Save key securely')}</form>`,async(v,d)=>{await api('/api/garmin/configure',v);await saved(d,'Key saved. Live sync is still unverified.');});}
function garminSync(){const start=new Date(state.today+'T12:00:00Z');start.setUTCDate(start.getUTCDate()-6);modal('Sync your Garmin records',`<form><p>Choose up to 31 days. A repeat sync updates records using their source identities.</p>${field('start','From',start.toISOString().slice(0,10),'date','required')}${field('end','Through',state.today,'date','required')}${saveButton('Sync now')}</form>`,async(v,d)=>{await api('/api/garmin/sync',v);await saved(d,'Garmin sync complete.');});}
function duplicates(){const pending=state.activities.filter(a=>a.pendingDuplicate);modal('Review overlapping records',`<p>Candidates stay out of totals until you decide. Source files remain preserved.</p>${pending.length?pending.map(a=>{const other=state.activities.find(x=>x.id===a.pendingDuplicate);return`<section class="duplicate-pair"><h3>${esc(a.title)} · ${esc(a.provider)}</h3><p>${formatDate(a.date)} · ${a.distanceKm??'—'} km · ${a.movingSeconds??'—'} seconds</p><p>Possible match: ${esc(other?.title||'Unavailable')} · ${esc(other?.provider)} · ${other?.distanceKm??'—'} km · ${other?.movingSeconds??'—'} seconds</p><button class="primary" data-merge="${esc(a.id)}" data-keep="${esc(a.pendingDuplicate)}">Merge into existing session</button>${link('Keep as a separate session',`data-separate="${esc(a.id)}"`)}</section>`;}).join(''):'<div class="quiet-empty"><h3>No uncertain matches.</h3><p>No duplicates waiting for review.</p></div>'}${state.merges.filter(m=>!m.undone).map(m=>link('Undo a previous merge',`data-undo="${esc(m.id)}"`)).join('')}`);}
async function outbox(){const keys=await local.keys(),pending=await Promise.all(keys.filter(k=>String(k).startsWith('outbox:')).map(async key=>({key,...await local.read(key)}))),drafts=keys.filter(k=>String(k).startsWith('draft:'));modal('Kept on this device',`<p>${pending.length} saves waiting to sync. ${drafts.length} unfinished check-in drafts.</p>${link('Try syncing now','data-action="sync"')}${pending.map(p=>`<section><h3>${p.conflict?'Two versions need your choice':'Waiting for connection'}</h3><p>${esc(p.path.split('/').at(-1))} · ${formatDate(p.at)}</p>${p.conflict?`<details><summary>Compare versions</summary><h4>Your draft</h4><pre>${esc(JSON.stringify(p.payload.feedback||p.payload.sleep||p.payload.activity||p.payload.plan||p.payload.settings,null,2))}</pre><h4>Current server version</h4><pre>${esc(JSON.stringify(p.current,null,2))}</pre></details>${link('Save my draft over the server version',`data-conflict="${esc(p.key)}"`)}`:''}${link('Discard this queued save',`data-discard="${esc(p.key)}"`)}</section>`).join('')}${drafts.map(k=>{const a=state.activities.find(a=>a.id===String(k).slice(6));return a?link(`Continue ${a.title}`,`data-checkin="${esc(a.id)}"`):'';}).join('')}`);}
async function trash(){const result=await api('/api/trash',{});modal('Archived, not erased',result.records.length?result.records.map(r=>`<section><h3>${esc(r.title||r.date)}</h3><p>${esc(r.kind)} · ${esc(r.date)}</p>${link('Restore record',`data-recover="${esc(r.id)}" data-kind="${r.kind}" data-revision="${r.revision}"`)}</section>`).join(''):'<p>No archived records.</p>');}
async function saveFeedback(){clearTimeout(draftTimer);await saveDraft();const result=await queueSave('/api/feedback',{activityId:selectedId,feedback:feedbackDraft,revision:feedbackRevision});await local.remove(`draft:${selectedId}`);if(result.queued){toast('Check-in kept on this device. It will sync when connected.');await go('sessions');}else{await refresh();await go('session',selectedId);toast('Your side of the story is saved.');}}
async function lock(){if(await updateQueueStatus())return outbox();const drafts=(await local.keys()).filter(k=>String(k).startsWith('draft:'));if(drafts.length){modal('Keep your unfinished thoughts',`<p>You have ${drafts.length} drafts on this device. Finish them or explicitly discard them before clearing this browser.</p>${link('Review drafts','data-action="outbox"')}${link('Discard drafts & lock','data-action="force-lock"')}`);return;}await api('/api/logout',{});await local.clear();state=null;csrf=null;loginScreen();}
async function act(name){if(name==='quick-log'){modal('What would you like to record?',`${link('A session','data-action="new-activity"')}${link('Sleep or a morning note','data-action="sleep-note"')}${link('A planned session','data-action="new-plan"')}`);return;}if(name==='focus-note'){document.getElementById('checkin-note').focus();return;}if(name==='save-feedback')return saveFeedback();if(name==='new-activity')return manualActivity();if(name==='edit-activity')return manualActivity(detail?.activity||activity());if(name==='sleep-note')return sleepNote();if(name==='new-plan')return planEditor();if(name==='link-plan')return planEditor(state.plans.find(p=>p.activityId===selectedId),selectedId);if(name==='session-evidence')return sessionEvidence();if(name==='import')return importFile();if(name==='export')return backupExport();if(name==='restore')return backupRestore();if(name==='garmin-info')return modal('Ready when your watch is',`<p>Garmin Personal API can provide activities, nightly sleep totals, estimated stages and available overnight HRV. We’ll show only fields your watch supplies.</p><p>You can keep morning notes now. No invented sleep scores or readiness verdicts.</p>${link('Open connection settings','data-go="data"')}`);if(name==='garmin-config')return garminConfigure();if(name==='garmin-sync')return garminSync();if(name==='garmin-disconnect'){await api('/api/garmin/disconnect',{});await refresh();render();toast('Garmin disconnected. Imported records are kept.');return;}if(name==='duplicates')return duplicates();if(name==='outbox')return outbox();if(name==='sync'){await syncQueue();return outbox();}if(name==='trash')return trash();if(name==='lock')return lock();if(name==='force-lock'){for(const k of await local.keys())if(String(k).startsWith('draft:'))await local.remove(k);activeDialog?.close();return lock();}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a,[role="button"]');if(!b)return;const d=b.dataset;if(!Object.keys(d).length)return;e.preventDefault();try{if(d.morning){const old=state.sleeps.find(s=>s.date===state.today&&s.type==='night');const r=await queueSave('/api/sleep',{sleep:{id:old?.id,date:state.today,rest:d.morning},revision:old?.revision||0});await refresh();render();toast(r.queued?'Morning note waiting to sync.':'Morning note saved.');return;}if(d.go){activeDialog?.close();return await go(d.go);}if(d.session){activeDialog?.close();return await go('session',d.session);}if(d.checkin){activeDialog?.close();return await go('checkin',d.checkin);}if(d.action)return await act(d.action);if(d.answer){const value=d.answer==='effort'?Number(d.value):d.value;feedbackDraft[d.answer]=value;if(d.answer==='discomfort'&&value==='none')feedbackDraft.location=null;await saveDraft();const scroll=scrollY;render();scrollTo(0,scroll);document.querySelector(`[data-answer="${d.answer}"][data-value="${d.value}"]`)?.focus({preventScroll:true});return;}if(d.filter){historyFilter=d.filter;render();return;}if(d.range){exploreRange=d.range;render();return;}if(d.sleepDays){sleepDays=Number(d.sleepDays);render();return;}if(d.night){activeDialog?.close();nightId=d.night;return await go('sleep');}if(d.sleepEdit)return sleepNote(state.sleeps.find(s=>s.id===d.sleepEdit));if(d.plan)return planEditor(state.plans.find(p=>p.id===d.plan));if(d.insight)return insightEvidence(state.insights.find(i=>i.id===d.insight));if(d.split!==undefined){const a=route==='session'?(detail?.activity||activity()):state.activities.find(a=>a.id===state.insights[0]?.activityId),s=a?.splits?.[Number(d.split)];if(s)document.getElementById('split-detail').textContent=`${s.distanceKm.toFixed(2)} km · ${pace(s.paceSeconds)} /km${s.durationSeconds?' · '+pace(s.durationSeconds)+' duration':''}${s.origin?' · '+s.origin:''}`;return;}if(d.history){const h=await api(`/api/history?kind=${d.history}&id=${encodeURIComponent(d.id)}`);modal('Edit history',h.revisions.length?h.revisions.map(r=>`<details><summary>Revision ${r.revision} · ${formatDate(r.updated)}</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details>`).join(''):'<p>No earlier revisions. The original record is current.</p>');return;}if(d.weightEdit)return editWeight(state.weights.find(w=>w.id===d.weightEdit));if(d.weight){const w=state.weights.find(w=>w.id===d.weight);document.getElementById('weight-point-detail').innerHTML=`${link('Correct this measurement',`data-weight-edit="${esc(w.id)}"`)}`;document.getElementById('weight-point-detail').insertAdjacentText('afterbegin',`${formatDate(w.date,{day:'numeric',month:'long',year:'numeric'})} · ${w.kg.toFixed(1)} kg · ${w.provider}`);return;}if(d.archive){const collection={activity:'activities',sleep:'sleeps',weight:'weights',plan:'plans'}[d.archive],r=state[collection].find(r=>r.id===d.id);await queueSave('/api/archive',{kind:d.archive,id:r.id,revision:r.revision});activeDialog?.close();await refresh();await go(d.archive==='sleep'?'sleep':'sessions');toast('Archived. Restore it in Data & privacy.');return;}if(d.recover){await queueSave('/api/archive',{kind:d.kind,id:d.recover,revision:Number(d.revision),restore:true});await refresh();render();return trash();}if(d.merge){await api('/api/duplicates/merge',{keepId:d.keep,removeId:d.merge});await refresh();render();return duplicates();}if(d.separate){const a=state.activities.find(a=>a.id===d.separate);await api('/api/duplicates/keep',{id:a.id,revision:a.revision});await refresh();render();return duplicates();}if(d.undo){await api('/api/duplicates/undo',{id:d.undo});await refresh();render();return duplicates();}if(d.discard){await local.remove(d.discard);return outbox();}if(d.conflict){const p=await local.read(d.conflict),payload={...p.payload,revision:p.current?.revision||0,mutationId:crypto.randomUUID()};const resolution=await queueSave(p.path,payload);await local.remove(d.conflict);if(payload.activityId){const draft=await local.read(`draft:${payload.activityId}`);if(draft&&JSON.stringify(draft.value)===JSON.stringify(payload.feedback))await local.remove(`draft:${payload.activityId}`);else if(draft)await local.write(`draft:${payload.activityId}`,{...draft,revision:resolution.result?.revision||payload.revision+1});}await refresh();if(route==='checkin')await loadDraft();render();return outbox();}}catch(err){const alert=activeDialog?.querySelector('.form-error');if(alert)alert.textContent=err.message;else toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='checkin-note'){feedbackDraft.note=e.target.value;clearTimeout(draftTimer);draftTimer=setTimeout(()=>saveDraft().catch(()=>toast('Device storage is unavailable. Keep this page open until you save.')),150);}if(e.target.id==='leg-context'){feedbackDraft.legs=e.target.value||null;saveDraft();}if(e.target.id==='history-search'){historyQuery=e.target.value;render();document.getElementById('history-search').focus();}});
document.addEventListener('submit',async e=>{if(e.target.id!=='preferences')return;e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f));try{const r=await queueSave('/api/settings',{settings:{...v,morningPrompt:f.morningPrompt.checked,showSpo2:f.showSpo2.checked},revision:state.settings.revision||0});await refresh();render();toast(r.queued?'Preferences waiting to sync.':'Preferences saved.');}catch(err){toast(err.message);}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [role="button"]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
function loginScreen(message=''){document.documentElement.dataset.theme='dark';root.innerHTML=`<main class="unlock" id="main" tabindex="-1"><div class="brand">STRIDE<span>INTELLIGENCE</span></div><div class="unlock-mark">${icon('sessions')}</div>${label('A PRIVATE TRAINING JOURNAL')}<h1>Your effort.<br>A little more<br>understanding.</h1><p>Unlock your own space for training, sleep and the patterns in between.</p><form id="login"><label>Owner key<input name="key" type="password" autocomplete="current-password" required autofocus></label>${primary('Unlock journal','type="submit"','lock')}<p class="form-error" role="alert">${esc(message)}</p></form><details><summary>Where is my owner key?</summary><p>On the computer running STRIDE, open <code>STRIDE_ASTRA_v1_FINAL/.stride-data/owner-key.txt</code>. Keep this key private.</p></details></main>`;document.getElementById('login').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const r=await api('/api/login',{key:e.target.key.value});csrf=r.csrf;await refresh();route='today';render();window.scrollTo(0,0);await syncQueue();}catch(err){root.querySelector('.form-error').textContent=err.message;e.submitter.disabled=false;}};}
async function boot(){try{const auth=await api('/api/auth');if(!auth.authenticated){loginScreen();return;}csrf=auth.csrf;await refresh();if(['session','checkin'].includes(route)){selectedId=await local.read('selectedId');if(state.activities.some(a=>a.id===selectedId)){if(route==='checkin')await loadDraft();else detail=await api(`/api/activity/${encodeURIComponent(selectedId)}`);}else route='sessions';}render();await syncQueue();}catch(err){const cached=await local.read('snapshot');if(cached&&!err.status){state=cached;offline=true;route='today';applyTheme();render();toast('Offline view. Your new check-ins will stay on this device.');}else loginScreen(err.message);}if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
addEventListener('online',async()=>{try{const auth=await api('/api/auth');csrf=auth.csrf;if(csrf){await syncQueue();await refresh();if(route!=='checkin')render();}else toast('Unlock again to sync your saved work.');}catch{}});
addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(state&&next!==route&&['today','sessions','sleep','explore','plan','data'].includes(next)){route=next;render();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&route==='checkin'&&feedbackDraft)saveDraft().catch(()=>{});});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
boot();

